<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $current = sd_social_current_filter(); $filters = array( 'public' => __( 'All public activity', 'social-discovery' ), 'mine' => __( 'My activity', 'social-discovery' ) ); if ( function_exists( 'bp_is_active' ) && bp_is_active( 'friends' ) && is_user_logged_in() ) { $filters['friends'] = __( 'Friends', 'social-discovery' ); } if ( function_exists( 'bp_is_active' ) && bp_is_active( 'activity' ) && is_user_logged_in() ) { $filters['mentions'] = __( 'Mentions', 'social-discovery' ); } ?><nav class="sd-feed-filters" aria-label="<?php esc_attr_e( 'Feed filters', 'social-discovery' ); ?>"><?php foreach ( $filters as $key => $label ) : ?><a class="<?php echo $current === $key ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( 'feed', $key ) ); ?>"><?php echo esc_html( $label ); ?></a><?php endforeach; ?></nav>
